# helper: iterate through all pages for a query and find exact-name matches

def find_exact_matches(query, target_name, page_limit=20):
    matches = []
    page_index = 0
    target_l = target_name.strip().lower()
    while True:
        resp = apis.amazon.search_products(query=query, page_index=page_index, page_limit=page_limit)
        if not resp:
            break
        for p in resp:
            name = (p.get('name') or '').strip()
            if name.lower() == target_l:
                matches.append({
                    'product_id': p.get('product_id'),
                    'name': p.get('name'),
                    'price': p.get('price'),
                    'rating': p.get('rating'),
                    'delivery_days': p.get('delivery_days'),
                    'inventory_quantity': p.get('inventory_quantity'),
                    'seller_id': p.get('seller_id'),
                    'variations': p.get('variations')
                })
        page_index += 1
    return matches

exact_matches = {}
for item_name, qty in required_items:
    matches = find_exact_matches(query=item_name, target_name=item_name)
    exact_matches[item_name] = matches
    print('\nitem', item_name, 'matches_count', len(matches))
    # print up to 10
    for m in matches[:10]:
        print(m['product_id'], m['price'], m['rating'], m['delivery_days'], m['inventory_quantity'], 'seller', m['seller_id'])

# selection rule: max inventory_quantity, then max rating, then min price, then min product_id
selected = {}
for item_name, qty in required_items:
    matches = exact_matches[item_name]
    if not matches:
        print('NO EXACT MATCHES FOUND FOR', item_name)
        continue
    def sort_key(m):
        return (-float(m['inventory_quantity'] or 0), -float(m['rating'] or 0), float(m['price'] or 0), int(m['product_id']))
    matches_sorted = sorted(matches, key=sort_key)
    chosen = matches_sorted[0]
    selected[item_name] = chosen
    print('\nCHOSEN for', item_name)
    print(chosen)

print('\nselected_product_ids', {k:v['product_id'] for k,v in selected.items()})

